"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6687],{96687:a=>{a.exports=JSON.parse('{"slug":"rosatom-plavuchie-aes-indoneziya-eksport","locale":"zh","title":"Rosatom将首次向海外销售浮动核电站电力","description":"Rosatom签署全球首份浮动核电站电力出口协议：为印尼提供2座机组、总计200MW。分析其经济意义。","blocks":[{"id":"b001","kind":"paragraph","text":"Rosatom与印尼PT Pembangkit Listrik Nuklir于2026年十月16日俄罗斯能源周签署协议，为印尼东部供电。俄罗斯将向北马鲁古省哈马黑拉岛北部提供2座PEB-100浮动核电机组，总200MW。Rosatom总经理阿列克谢\xb7利哈乔夫称，这是全球首份浮动核电机组电力出口协议，也是印尼首个核能项目。"},{"id":"b002","kind":"paragraph","text":"浮动核电站是建在驳船上的小型核电设施，在船厂建造后拖到缺电网、缺大型厂址的地方。目前全球仅一座运行，即楚科奇的罗蒙诺索夫院士号，70MW。Kept分析师谢尔盖\xb7罗任科认为速度是主要优势：投产比需8–10年的常规核电快2–3倍。"},{"id":"b003","kind":"paragraph","text":"交易模式重要。Rosatom不仅卖设备，还卖整个运营期的电力，监管许可为60年，利哈乔夫预计可延长。印尼方面称由私人投资、商业运作，不使用本国预算。合同主要条件生效后5年预计首次供电。Rosatom还建议建设大型陆上核电，并在东南亚和非洲开展类似谈判。"},{"id":"b004","kind":"paragraph","text":"成本未披露。俄罗斯参考项目是楚科奇Baimsky矿业综合体的4座浮动机组、总420MW，2021年含税估价190.2十亿卢布，电价约每千瓦时6卢布，首座计划2028年投产。分析师认为，必须形成8–10座机组系列后才能判断经济性；此前高启动成本使电价难预测。"},{"id":"b005","kind":"paragraph","text":"俄罗斯出口收入通常跟随油气价格。按几十年售电的合同则可独立于油价创造外汇；此类合同越多，卢布和预算对单一资源依赖越低。同时浮动机组订单为本国船厂和反应堆制造商提供工作。"},{"id":"b006","kind":"paragraph","text":"普通人近年不会直接感到变化：电力最早5年后才来，收入分布数十年。长期问题是石油不再居首时，俄罗斯从哪里赚外汇。项目是否划算，要等电价和成本公开，目前尚未披露。"},{"id":"b007","kind":"heading","text":"Rosatom将在印尼建设什么？"},{"id":"b008","kind":"paragraph","text":"北马鲁古省哈马黑拉岛北部的2座PEB-100浮动核电机组，总200MW。协议于2026年十月16日签署，主要合同条件生效后5年预计首次供电。"},{"id":"b009","kind":"heading","text":"浮动核电站是什么？"},{"id":"b010","kind":"paragraph","text":"船厂建造、拖至工作地点的驳船小型核电站。目前唯一运行的罗蒙诺索夫院士号70MW，为楚科奇供电。"},{"id":"b011","kind":"heading","text":"浮动核电站多少钱？"},{"id":"b012","kind":"paragraph","text":"印尼成本未披露。楚科奇4座机组2021年含税估190.2十亿卢布，当时电价约每千瓦时6卢布。"}],"sources":[{"label":"Rosatom将为印尼提供两座浮动核电机组","url":"https://www.kommersant.ru/doc/9040651"},{"label":"Rosatom签署印尼两座浮动核电站协议","url":"https://www.vedomosti.ru/business/news/2026/10/16/1237826-rosatom-podpisal-soglashenie"},{"label":"俄罗斯达成全球首次浮动核电机组国际供电协议","url":"https://lenta.ru/news/2026/10/16/rossiya-soglasovala-pervye-v-mire-mezhdunarodnye-postavki-s-plavuchih-atomnyh-energoblokov"}],"sourceBodySha256":"364e6fd7aa47727920a3c88d5445a62573e93f518bfc9c74e7e8f7d9926d5290"}')}}]);